cd "/Users/luisdehlwes/Documents/00_Events/EHL Finale/worktrees/luis-competitors" && python3 -I -c "
import openpyxl,collections
wb=openpyxl.load_workbook('data/G60_feedback_hackathon.xlsx',read_only=True)
for ws in wb.worksheets:
    rows=ws.iter_rows(values_only=True)
    hdr=next(rows); print(ws.title,hdr)
    idx={h:i for i,h in enumerate(hdr)}
    c=collections.Counter()
    for r in rows:
        l2=None;ft=None
        for k in idx:
            if k and 'LEVEL2' in str(k).upper(): l2=r[idx[k]]
            if k and ('TYPE' in str(k).upper() or 'LEVEL1' in str(k).upper()): ft=(ft or '')+'|'+str(r[idx[k]])
        if l2 in ('Exterior design','Drivetrain','Interior acoustics','General enquiry: customer feedback','no_class_found'): c[(l2,ft)]+=1
    for k,v in c.most_common(40): print(v,k)
    break
"

