input.command:
cd "/Users/luisdehlwes/Documents/00_Events/EHL Finale/worktrees/luis-competitors" && python3 -I -c "
import json,collections
th=json.load(open('competitors/themes.json'))
ids={t['id'] for t in th['themes']}; l2=set(th['vfc_level2_to_theme'])
recs=[]
for i,l in enumerate(open('competitors/raw/cn_german_g68.jsonl',encoding='utf-8')):
  try: recs.append(json.loads(l))
  except Exception as e: print('JSONERR line',i+1,e)
bad=0
featth={'F01':'hmi_infotainment','F02':'hmi_infotainment','F03':'climate','F04':'hmi_infotainment','F05':'connectivity_app_digital','F06':'connectivity_app_digital','F07':'access_locking','F08':'adas_parking','F09':'adas_parking','F10':'seats_comfort','F11':'seats_comfort','F12':'seats_comfort','F13':'ride_handling','F14':'ride_handling','F15':'range_charging_efficiency','F16':'range_charging_efficiency','F17':'space_practicality','F18':'space_practicality','F19':'audio_acoustics','F20':'interior_design_quality'}
for r in recs:
  if r['kind']=='feedback':
    if r['theme'] not in ids or (r['vfc_level2'] and r['vfc_level2'] not in l2) or r['feedback_type'] not in th['feedback_types'] or r['comparison'] not in (None,'competitor_advantage','bmw_advantage','parity') or r['powertrain'] not in ('ICE','PHEV','BEV','unknown'): print('BAD',r['record_id']); bad+=1
    if r['quote'] and len(r['quote'])>15: print('LONGQ',r['record_id'])
  if r['kind']=='equipment':
    if featth[r['feature'][:3]]!=r['theme'] or r['availability'] not in ('standard','optional','not_available','unknown'): print('BADE',r['record_id']); bad+=1
c=collections.Counter(r['record_id'] for r in recs); print('dups',[k for k,v in c.items() if v>1])
print('total',len(recs),'bad',bad)
print(collections.Counter(r['kind'] for r in recs))
for key in sorted({(r['model'],r['generation']) for r in recs}):
  fs=[r for r in recs if r['kind']=='feedback' and (r['model'],r['generation'])==key]
  eq=[r for r in recs if r['kind']=='equipment' and (r['model'],r['generation'])==key]
  print(key,'feedback',len(fs),'reviews',len({r['review_ref'] for r in fs}),dict(collections.Counter(r['source_type'] for r in fs)),'equip',len(eq), 'cmp',dict(collections.Counter(r['comparison'] for r in fs if r['comparison'])))
